factories["fleet.engine"] = function()
local planner = require("fleet.planner")
local motion = require("fleet.motion")
local net = require("fleet.net")
local M = {}

-- Receiver and runner share this state; only the runner calls turtle movement APIs.
function M.new(options)
  local self = {
    state = "idle", phase = "", reason = "", active = false, revision = 0,
    done = 0, total = 0, lastContact = options.now(), session = options.session,
    cache = {}, cacheOrder = {},
  }
  local cancelled = {}

  function self.snapshot()
    return {
      state = self.state, phase = self.phase, reason = self.reason,
      active = self.active, revision = self.revision, session = self.session,
      done = self.done, total = self.total, jobId = self.jobId,
      pose = self.mover and planner.copyPose(self.mover.pose) or nil,
      dug = self.mover and self.mover.dug or 0,
      fuel = options.turtle.getFuelLevel(), mining = options.mining(),
      owner = options.owner, label = options.label,
    }
  end

  local function publish() if options.publish then options.publish(self.snapshot()) end end

  function self.handle(sender, message)
    if sender ~= options.owner then return nil end
    if message.kind == "heartbeat" then
      self.lastContact = options.now()
      return nil
    end
    if message.kind ~= "command" or type(message.request) ~= "string" or #message.request > 100 then return nil end
    if message.session ~= self.session then
      return { request = message.request, ok = false, error = "Turtle restarted. Refresh its status." }
    end
    self.lastContact = options.now()
    if self.cache[message.request] then return self.cache[message.request] end
    local reply = { request = message.request, ok = false }
    local action = message.action
    if action == "start" then
      if self.active then reply.error = "Turtle is already working."
      elseif message.revision ~= self.revision then reply.error = "Status changed. Review and submit a fresh job."
      elseif not options.mining() then reply.error = "Equip a diamond pickaxe for mining programs."
      else
        local plan, why = planner.create(message.spec, message.pose)
        if not plan then reply.error = why
        elseif message.verifyGPS ~= true and message.verifyGPS ~= false then reply.error = "GPS choice is missing."
        elseif message.verifyGPS and message.pose.frame ~= "world" then reply.error = "GPS needs world coordinates."
        else
          self.plan, self.verifyGPS = plan, message.verifyGPS
          self.jobId, self.revision = message.request, self.revision + 1
          self.active, self.pending, self.cancel, self.pauseRequested, self.paused = true, true, false, false, false
          self.done, self.total, self.reason, self.state, self.phase = 0, plan.total, "", "starting", "checking"
          self.mover = nil
          reply.ok = true
        end
      end
    elseif not self.active or message.jobId ~= self.jobId then
      reply.error = "No matching active job."
    elseif action == "pause" then
      self.pauseRequested, reply.ok = true, true
    elseif action == "resume" then
      self.pauseRequested, self.paused, reply.ok = false, false, true
    elseif action == "cancel" then
      self.cancel, reply.ok = true, true
    else reply.error = "Unknown command." end
    self.cache[message.request] = reply
    self.cacheOrder[#self.cacheOrder + 1] = message.request
    if #self.cacheOrder > 64 then self.cache[table.remove(self.cacheOrder, 1)] = nil end
    publish()
    return reply
  end

  local function checkpoint()
    if self.cancel then error(cancelled, 0) end
    if options.now() - self.lastContact > net.LEASE then
      self.paused, self.state, self.reason = true, "paused", "Controller link lost. Reconnect, then resume."
    elseif self.pauseRequested then
      self.paused, self.state, self.reason = true, "paused", "Paused by controller."
    end
    while self.paused or self.pauseRequested do
      if self.cancel then error(cancelled, 0) end
      options.sleep(0.1)
    end
    if self.cancel then error(cancelled, 0) end
    -- Never act on a resume received before a renewed contact lease.
    if options.now() - self.lastContact > net.LEASE then return checkpoint() end
    self.state, self.reason = self.phase == "returning" and "returning" or "running", ""
  end

  local function retry(action)
    while true do
      checkpoint()
      local ok, why = action()
      if ok then return end
      self.paused, self.state, self.reason = true, "blocked", why
      publish()
      checkpoint()
    end
  end

  function self.runPending()
    if not self.pending then return false end
    self.pending = false
    local ok, why = pcall(function()
      if options.mark then options.mark({ jobId = self.jobId, program = self.plan.program }) end
      if self.verifyGPS then
        local x, y, z = options.locate()
        if not x then error("GPS unavailable. Check hosts or use a manually verified position.", 0) end
        local p = self.plan.origin
        if math.abs(x - p.x) > 0.1 or math.abs(y - p.y) > 0.1 or math.abs(z - p.z) > 0.1 then
          error("GPS does not match the entered starting position. No movement made.", 0)
        end
      end
      self.mover = motion.new(options.turtle, self.plan.origin, checkpoint)
      self.phase = "clearing"
      for index = 1, self.total do
        local target = planner.target(self.plan, index)
        retry(function() return self.mover.step(target, true, self.plan) end)
        self.done = index
      end
      self.phase = "returning"
      -- Rise in the cleared column, then cross above the volume without digging.
      for _, axis in ipairs({ "y", "x", "z" }) do
        while self.mover.pose[axis] ~= self.plan.origin[axis] do
          local target = planner.copyPose(self.mover.pose)
          target[axis] = target[axis] + (target[axis] < self.plan.origin[axis] and 1 or -1)
          retry(function() return self.mover.step(target, false) end)
        end
      end
      retry(function() return self.mover.face(self.plan.origin.heading) end)
    end)
    if not ok and why == "Terminated" then error(why, 0) end
    self.active, self.paused, self.pauseRequested = false, false, false
    if ok then self.state, self.reason = "completed", "Returned to the starting position."
    elseif why == cancelled then self.state, self.reason = "cancelled", "Stopped in place. Check position before a new job."
    else self.state, self.reason = "error", tostring(why) end
    if options.clearMark then options.clearMark() end
    publish()
    return true
  end

  return self
end

return M

end
factories["fleet.motion"] = function()
local planner = require("fleet.planner")
local M = {}

function M.protected(name)
  return name:match("^computercraft:") or name:find("chest", 1, true)
    or name:find("shulker_box", 1, true) or name == "minecraft:barrel"
    or name == "minecraft:spawner" or name == "minecraft:trial_spawner"
end

function M.new(api, pose, checkpoint, changed)
  local self = { pose = planner.copyPose(pose), dug = 0 }
  checkpoint, changed = checkpoint or function() end, changed or function() end

  function self.face(heading)
    while self.pose.heading ~= heading do
      checkpoint()
      local left = (heading - self.pose.heading) % 4 == 3
      local ok, why = (left and api.turnLeft or api.turnRight)()
      if not ok then return false, why or "Cannot turn." end
      self.pose.heading = (self.pose.heading + (left and -1 or 1)) % 4
      changed()
    end
    return true
  end

  local function fuel()
    local level = api.getFuelLevel()
    if level == "unlimited" or level > 0 then return true end
    local selected = api.getSelectedSlot()
    api.select(16)
    local ok = api.refuel(1)
    api.select(selected)
    return ok, "Out of fuel. Put fuel in slot 16, then resume."
  end

  local function emptyCargoSlots()
    local empty = 0
    for slot = 1, 15 do
      if api.getItemCount(slot) == 0 then empty = empty + 1 end
    end
    return empty
  end

  local function compactCargo()
    -- Merge only compatible cargo stacks. Native transfers enforce item/component
    -- compatibility and stack limits; fuel slot 16 is never a source or target.
    for target = 1, 14 do
      if api.getItemCount(target) > 0 and api.getItemSpace(target) > 0 then
        for source = target + 1, 15 do
          checkpoint()
          if api.getItemCount(source) > 0 then
            api.select(source)
            if api.compareTo(target) then
              checkpoint()
              api.transferTo(target)
            end
          end
          if api.getItemSpace(target) == 0 then break end
        end
      end
    end
  end

  local function space()
    if emptyCargoSlots() < 2 then compactCargo() end
    if emptyCargoSlots() < 2 then return false, "Inventory nearly full. Empty cargo slots, then resume." end
    -- Drops search from the selected slot. Always start at 1 so partial stacks
    -- get used before later empty slots, instead of spreading one item per slot.
    api.select(1)
    return true
  end

  function self.step(target, mayDig, plan)
    local p = self.pose
    local dx, dy, dz = target.x - p.x, target.y - p.y, target.z - p.z
    if math.abs(dx) + math.abs(dy) + math.abs(dz) ~= 1 then
      return false, "Route error: target must be adjacent."
    end
    if mayDig and (not plan or not planner.contains(plan, target)) then
      return false, "Route error: digging outside the selected volume."
    end
    local move, inspect, dig
    if dy ~= 0 then
      move = dy > 0 and api.up or api.down
      inspect = dy > 0 and api.inspectUp or api.inspectDown
      dig = dy > 0 and api.digUp or api.digDown
    else
      local heading = dx == 1 and 1 or dx == -1 and 3 or dz == 1 and 2 or 0
      local ok, why = self.face(heading)
      if not ok then return false, why end
      move, inspect, dig = api.forward, api.inspect, api.dig
    end
    for _ = 1, 16 do
      checkpoint()
      local ok, why = fuel()
      if not ok then return false, why end
      local exists, block = inspect()
      if exists then
        if block.name == "minecraft:water" or block.name == "minecraft:lava"
          or block.name == "minecraft:bubble_column" then
          return false, "Fluid encountered: " .. block.name .. ". Drain it before resuming."
        end
        if not mayDig then return false, "Return path blocked. Clear it, then resume." end
        if M.protected(block.name) then return false, "Protected block: " .. block.name end
        ok, why = space()
        if not ok then return false, why end
        checkpoint()
        ok, why = dig()
        if not ok then return false, "Cannot dig: " .. (why or block.name) end
        self.dug = self.dug + 1
        changed()
      end
      checkpoint()
      ok, why = move()
      if ok then
        p.x, p.y, p.z = target.x, target.y, target.z
        changed()
        return true
      end
      -- A falling block may have replaced the dug block. Never attack entities.
      local solid = inspect()
      if not solid then return false, "Movement blocked by entity or world boundary: " .. (why or "unknown") end
    end
    return false, "Repeated falling blocks. Stabilize the area, then resume."
  end
  return self
end

return M

end
factories["fleet.net"] = function()
local M = { VERSION = 1, PROTOCOL = "turtle-fleet/1", LEASE = 12, STALE = 8 }

function M.open()
  local count = 0
  for _, side in ipairs(peripheral.getNames()) do
    if peripheral.hasType(side, "modem") and peripheral.call(side, "isWireless") then
      rednet.open(side)
      count = count + 1
    end
  end
  assert(count > 0, "Attach a wireless or Ender modem, then run Fleet again.")
end

function M.valid(message, group)
  return type(message) == "table" and message.version == M.VERSION
    and message.group == group and type(message.kind) == "string"
end

function M.packet(group, kind, body)
  local packet = body or {}
  packet.version, packet.group, packet.kind = M.VERSION, group, kind
  return packet
end

function M.send(id, group, kind, body)
  return rednet.send(id, M.packet(group, kind, body), M.PROTOCOL)
end

function M.broadcast(group, kind, body)
  rednet.broadcast(M.packet(group, kind, body), M.PROTOCOL)
end

return M

end
factories["fleet.planner"] = function()
-- All geometry is independent of Minecraft, and uses inclusive block coordinates.
local M = {}
M.MAX_EDGE, M.MAX_DEPTH, M.MAX_VOLUME = 256, 384, 2000000
M.directions = {
  [0] = { x = 0, z = -1, name = "north" },
  [1] = { x = 1, z = 0, name = "east" },
  [2] = { x = 0, z = 1, name = "south" },
  [3] = { x = -1, z = 0, name = "west" },
}
M.programs = {
  { id = "flatten", name = "Flatten by corners", needsWorld = true },
  { id = "quarry", name = "Clear width/length/depth", needsWorld = false },
}

function M.integer(n, low, high)
  return type(n) == "number" and n == n and n % 1 == 0 and n >= low and n <= high
end

function M.validPose(p)
  return type(p) == "table" and M.integer(p.x, -30000000, 30000000)
    and M.integer(p.z, -30000000, 30000000) and M.integer(p.y, -30000, 30000)
    and M.integer(p.heading, 0, 3) and (p.frame == "world" or p.frame == "local")
end

function M.copyPose(p)
  return { x = p.x, y = p.y, z = p.z, heading = p.heading, frame = p.frame }
end

function M.create(spec, pose)
  if type(spec) ~= "table" or not M.validPose(pose) then
    return nil, "Invalid job or starting position."
  end
  local p = { origin = M.copyPose(pose), program = spec.program }
  if spec.program == "flatten" then
    if pose.frame ~= "world" then return nil, "Corners require world coordinates." end
    for _, key in ipairs({ "x1", "z1", "x2", "z2" }) do
      if not M.integer(spec[key], -30000000, 30000000) then
        return nil, "Corner coordinates must be whole numbers."
      end
    end
    if not M.integer(spec.floorY, -30000, 30000) then return nil, "Invalid floor Y." end
    if (pose.x ~= spec.x1 and pose.x ~= spec.x2)
      or (pose.z ~= spec.z1 and pose.z ~= spec.z2) then
      return nil, "Place the turtle above a corner of this rectangle."
    end
    local otherX = pose.x == spec.x1 and spec.x2 or spec.x1
    local otherZ = pose.z == spec.z1 and spec.z2 or spec.z1
    p.width, p.length = math.abs(otherX - pose.x) + 1, math.abs(otherZ - pose.z) + 1
    p.u = { x = otherX >= pose.x and 1 or -1, z = 0 }
    p.v = { x = 0, z = otherZ >= pose.z and 1 or -1 }
    p.depth = pose.y - 1 - spec.floorY
  elseif spec.program == "quarry" then
    p.width, p.length, p.depth = spec.width, spec.length, spec.depth
    p.u, p.v = M.directions[(pose.heading + 1) % 4], M.directions[pose.heading]
  else
    return nil, "Unknown program."
  end
  if not M.integer(p.width, 1, M.MAX_EDGE) or not M.integer(p.length, 1, M.MAX_EDGE) then
    return nil, "Width and length must be 1-256 blocks (corners are inclusive)."
  end
  if not M.integer(p.depth, 1, M.MAX_DEPTH) then
    return nil, "Remove 1-384 layers; floor Y must be at least 2 below the turtle."
  end
  p.area, p.total = p.width * p.length, p.width * p.length * p.depth
  if p.total > M.MAX_VOLUME then return nil, "Job exceeds 2,000,000 blocks." end
  p.topY, p.floorY = pose.y - 1, pose.y - p.depth - 1
  local farX = pose.x + p.u.x * (p.width - 1) + p.v.x * (p.length - 1)
  local farZ = pose.z + p.u.z * (p.width - 1) + p.v.z * (p.length - 1)
  if not M.integer(farX, -30000000, 30000000) or not M.integer(farZ, -30000000, 30000000)
    or not M.integer(p.floorY, -30000, 30000) then return nil, "Area is outside coordinate limits." end
  p.minX, p.maxX = math.min(pose.x, farX), math.max(pose.x, farX)
  p.minZ, p.maxZ = math.min(pose.z, farZ), math.max(pose.z, farZ)
  local last = M.target(p, p.total)
  p.fuel = p.total + math.abs(last.x - pose.x) + math.abs(last.z - pose.z) + p.depth
  return p
end

-- Adjacent serpentine layers run in opposite directions. No path table is allocated.
function M.target(p, index)
  assert(M.integer(index, 1, p.total), "Invalid route index")
  local layer = math.floor((index - 1) / p.area)
  local cell = (index - 1) % p.area
  if layer % 2 == 1 then cell = p.area - 1 - cell end
  local row, column = math.floor(cell / p.width), cell % p.width
  if row % 2 == 1 then column = p.width - 1 - column end
  return {
    x = p.origin.x + p.u.x * column + p.v.x * row,
    z = p.origin.z + p.u.z * column + p.v.z * row,
    y = p.topY - layer,
  }
end

function M.contains(p, target)
  return target.x >= p.minX and target.x <= p.maxX and target.z >= p.minZ
    and target.z <= p.maxZ and target.y > p.floorY and target.y <= p.topY
end

return M

end
factories["fleet.ui"] = function()
local M = {}

function M.header(title)
  term.clear()
  term.setCursorPos(1, 1)
  print(title)
  local width = term.getSize()
  print(string.rep("-", width))
end

function M.text(label, default)
  print(label .. (default ~= nil and " [" .. tostring(default) .. "]" or ""))
  write("> ")
  local value = read()
  if value == "" and default ~= nil then return tostring(default) end
  return value
end

function M.number(label, default, low, high)
  while true do
    local value = tonumber(M.text(label, default))
    if value and value == value and value % 1 == 0 and value >= low and value <= high then return value end
    print("Whole number: " .. low .. " to " .. high)
  end
end

function M.wait()
  print("Press Enter to continue.")
  read()
end

function M.load(path)
  if not fs.exists(path) then return nil end
  local file = fs.open(path, "r")
  if not file then return nil end
  local value = textutils.unserialize(file.readAll())
  file.close()
  return value
end

function M.save(path, value)
  local file = assert(fs.open(path, "w"), "Cannot save " .. path)
  file.write(textutils.serialize(value))
  file.close()
end

function M.group(default)
  while true do
    local value = M.text("Fleet name", default or "fleet")
    if value:match("^[%w_-]+$") and #value <= 32 then return value end
    print("Use 1-32 letters, digits, - or _.")
  end
end

return M

end
local net = require("fleet.net")
local engine = require("fleet.engine")
local ui = require("fleet.ui")
local args = { ... }
assert(turtle, "Run the worker on a turtle.")
net.open()
local configPath, markPath = "/.fleet-worker", "/.fleet-interrupted"
local config = ui.load(configPath)
if type(config) ~= "table" or type(config.group) ~= "string" or type(config.owner) ~= "number" or args[1] == "setup" then
  ui.header("Turtle Fleet setup")
  print("Run the controller first to see its ID.")
  config = { group = ui.group(), owner = ui.number("Controller computer ID", nil, 0, 2147483647) }
  ui.save(configPath, config)
end
if not os.getComputerLabel() then os.setComputerLabel("Fleet turtle " .. os.getComputerID()) end

local function mining()
  for _, get in ipairs({ turtle.getEquippedLeft, turtle.getEquippedRight }) do
    local item = get()
    if item and item.name == "minecraft:diamond_pickaxe" then return true end
  end
  return false
end

local worker
local function announce(status, id)
  status = status or worker.snapshot()
  if id then net.send(id, config.group, "status", status)
  else net.broadcast(config.group, "status", status) end
end

-- A new session invalidates every command sent before a restart.
local session = tostring(os.getComputerID()) .. ":" .. tostring(os.epoch("utc"))
worker = engine.new({
  turtle = turtle, mining = mining, owner = config.owner, label = os.getComputerLabel(),
  now = os.clock, sleep = sleep, session = session, locate = function() return gps.locate(3) end,
  publish = function(status) announce(status) end,
  mark = function(value) ui.save(markPath, value) end,
  clearMark = function() if fs.exists(markPath) then fs.delete(markPath) end end,
})
if fs.exists(markPath) then
  worker.state, worker.reason = "restarted", "Interrupted job discarded. Verify position and submit a new job."
end

local function receiver()
  while true do
    local sender, message = rednet.receive(net.PROTOCOL)
    if net.valid(message, config.group) then
      if message.kind == "discover" then announce(worker.snapshot(), sender)
      else
        local reply = worker.handle(sender, message)
        if reply then net.send(sender, config.group, "ack", reply) end
      end
    end
  end
end

local function runner()
  while true do
    if not worker.runPending() then sleep(0.1) end
  end
end

local function display()
  while true do
    local s = worker.snapshot()
    announce(s)
    ui.header(os.getComputerLabel())
    print("ID " .. os.getComputerID() .. " | " .. config.group)
    print("Controller: " .. config.owner)
    print("State: " .. s.state)
    print("Cells: " .. s.done .. "/" .. s.total)
    print("Blocks dug: " .. s.dug)
    print("Fuel: " .. s.fuel .. " (slot 16)")
    if s.pose then print(("At: %d %d %d"):format(s.pose.x, s.pose.y, s.pose.z)) end
    if not s.mining then print("Equip a diamond pickaxe.") end
    print(s.reason)
    print("Ctrl+T: stop worker")
    sleep(2)
  end
end

-- Termination intentionally propagates. A restart never resumes physical work.
parallel.waitForAny(receiver, runner, display)
